# CODEFORGE FRONTEND UI + LIGHT THEME PATCH 006
# FRONTEND ONLY.
# Does NOT modify backend, API provider configuration, API endpoints, request payloads, or response handling.
#
# Changes:
# - Copilot: minimize, maximize/restore, exit controls
# - Copilot: keeps existing multiline coding input and working API send()/response flow unchanged
# - Global persistent dark/light toggle on every page
# - Dark theme remains the default/current design
# - Light theme reverses dark surfaces to white/light-gray while preserving CodeForge accent colors
#
# Run from either:
#   ...\codeforge
# or:
#   ...\codeforge\frontend

$ErrorActionPreference = "Stop"

$Here = (Get-Location).Path

if (Test-Path (Join-Path $Here "src\lib\components\AIAssistant.svelte")) {
    $Frontend = $Here
    $Project = Split-Path $Here -Parent
} elseif (Test-Path (Join-Path $Here "frontend\src\lib\components\AIAssistant.svelte")) {
    $Project = $Here
    $Frontend = Join-Path $Here "frontend"
} else {
    throw "CodeForge frontend not found. Run this patch from the project root or frontend folder."
}

$Assistant = Join-Path $Frontend "src\lib\components\AIAssistant.svelte"
$ThemeToggle = Join-Path $Frontend "src\lib\components\ThemeToggle.svelte"
$RootLayout = Join-Path $Frontend "src\routes\+layout.svelte"
$AppCss = Join-Path $Frontend "src\app.css"

foreach ($Required in @($Assistant, $RootLayout, $AppCss)) {
    if (!(Test-Path $Required)) {
        throw "Required frontend file not found: $Required"
    }
}

# Safety: refuse to replace an unexpected assistant implementation.
$CurrentAssistant = [System.IO.File]::ReadAllText($Assistant, [System.Text.Encoding]::UTF8)
if ($CurrentAssistant -notmatch "/api/assistant/chat" -or
    $CurrentAssistant -notmatch 'maxlength="12000"' -or
    $CurrentAssistant -notmatch "handleInputKeydown") {
    throw "AIAssistant.svelte does not match the current working multiline Copilot UI. No files were changed."
}

# Ensure this patch never silently removes the working API call.
if ($CurrentAssistant -notmatch "current_path:" -or
    $CurrentAssistant -notmatch "history," -or
    $CurrentAssistant -notmatch "data.reply") {
    throw "Working Copilot API request/response markers were not found. No files were changed."
}

$Stamp = Get-Date -Format "yyyyMMdd-HHmmss"
$BackupDir = Join-Path $Project "patch-backups\PATCH-006-UI-THEME-$Stamp"
New-Item -ItemType Directory -Path $BackupDir -Force | Out-Null

$Backups = @{}

function Backup-File([string]$Path) {
    if (Test-Path $Path) {
        $Name = [System.IO.Path]::GetFileName($Path)
        $Backup = Join-Path $BackupDir $Name
        Copy-Item $Path $Backup -Force
        $script:Backups[$Path] = $Backup
        Write-Host "[OK] backup: $Path"
    }
}

function Restore-Backups {
    foreach ($Path in $script:Backups.Keys) {
        $Backup = $script:Backups[$Path]
        if (Test-Path $Backup) {
            Copy-Item $Backup $Path -Force
        }
    }
}

function Write-Base64File([string]$Path, [string]$Data) {
    [System.IO.File]::WriteAllBytes($Path, [Convert]::FromBase64String($Data))
}

try {
    Backup-File $Assistant
    Backup-File $RootLayout
    Backup-File $AppCss
    Backup-File $ThemeToggle

    Write-Base64File $Assistant ""
    Write-Base64File $ThemeToggle ""
    Write-Base64File $RootLayout "PHNjcmlwdCBsYW5nPSJ0cyI+CiAgaW1wb3J0ICcuLi9hcHAuY3NzJzsKICBpbXBvcnQgVGhlbWVUb2dnbGUgZnJvbSAnJGxpYi9jb21wb25lbnRzL1RoZW1lVG9nZ2xlLnN2ZWx0ZSc7Cjwvc2NyaXB0PgoKPFRoZW1lVG9nZ2xlIC8+CjxzbG90IC8+Cg=="
    Write-Base64File $AppCss ""

    Write-Host "[OK] Copilot window controls installed"
    Write-Host "[OK] Global theme toggle installed"
    Write-Host "[OK] Light-theme surfaces installed"
    Write-Host "[OK] Backend/API files untouched"

    # Clear generated frontend output only. This does not affect source or API behavior.
    foreach ($Generated in @((Join-Path $Frontend ".svelte-kit"), (Join-Path $Frontend "build"))) {
        if (Test-Path $Generated) {
            Remove-Item $Generated -Recurse -Force -ErrorAction SilentlyContinue
        }
    }

    # Run frontend checks/build if npm is available. Roll back source if validation fails.
    Push-Location $Frontend
    try {
        $Npm = Get-Command npm -ErrorAction SilentlyContinue
        if ($Npm) {
            Write-Host "[CHECK] npm run check"
            & npm run check
            if ($LASTEXITCODE -ne 0) {
                throw "npm run check failed"
            }

            Write-Host "[CHECK] npm run build"
            & npm run build
            if ($LASTEXITCODE -ne 0) {
                throw "npm run build failed"
            }
        } else {
            Write-Host "[WARN] npm not found; frontend validation skipped."
        }
    }
    finally {
        Pop-Location
    }

    Write-Host ""
    Write-Host "[SUCCESS] Frontend-only UI/theme patch completed."
    Write-Host "Changed:"
    Write-Host "  frontend\src\lib\components\AIAssistant.svelte"
    Write-Host "  frontend\src\lib\components\ThemeToggle.svelte"
    Write-Host "  frontend\src\routes\+layout.svelte"
    Write-Host "  frontend\src\app.css"
    Write-Host ""
    Write-Host "No backend or AI API files were modified."
    Write-Host ""
    Write-Host "Restart frontend:"
    Write-Host "  npm run dev -- --host 127.0.0.1"
}
catch {
    Write-Host "[ERROR] $($_.Exception.Message)"
    Restore-Backups

    if ((Test-Path $ThemeToggle) -and !$script:Backups.ContainsKey($ThemeToggle)) {
        Remove-Item $ThemeToggle -Force -ErrorAction SilentlyContinue
    }

    Write-Host "[ROLLBACK] Original frontend files restored."
    exit 1
}
